1	/**
2	 * Centralized Resend email service.
3	 *
4	 * All send functions return `true` on success, `false` on failure — they never
5	 * throw. This lets callers fire-and-forget without wrapping in try/catch.
6	 */
7	import { Resend } from "resend";
8	
9	// ---------------------------------------------------------------------------
10	// Types
11	// ---------------------------------------------------------------------------
12	
13	export interface EmailOptions {
14	  /** Display name in the From field (e.g. "Cool Store"). Defaults to shopDisplayName. */
15	  senderName?: string | null;
16	  /** Cached Shopify store display name (from ShopSettings.shopName). Falls back to myshopify slug. */
17	  shopDisplayName?: string | null;
18	  /** Reply-to email for customer-facing emails. If empty, no reply-to header is added. */
19	  replyTo?: string | null;
20	}
21	
22	// ---------------------------------------------------------------------------
23	// Client singleton
24	// ---------------------------------------------------------------------------
25	
26	let client: Resend | null = null;
27	
28	function getClient(): Resend | null {
29	  if (client) return client;
30	  const apiKey = process.env.RESEND_API_KEY;
31	  if (!apiKey) {
32	    console.warn("[email] RESEND_API_KEY not set — emails will be skipped");
33	    return null;
34	  }
35	  client = new Resend(apiKey);
36	  return client;
37	}
38	
39	/**
40	 * Returns true if the Resend API key is configured and the client can be
41	 * initialized. Callers use this to show actionable diagnostics in the UI
42	 * (e.g. "API key missing" vs "send failed") without attempting a live send.
43	 */
44	export function isEmailConfigured(): boolean {
45	  return Boolean(process.env.RESEND_API_KEY);
46	}
47	
48	function getRawFromEmail(): string {
49	  return process.env.RESEND_FROM_EMAIL || "noreply@example.com";
50	}
51	
52	function shopFallbackName(shop: string, options?: EmailOptions): string {
53	  return options?.shopDisplayName?.trim() || shop.replace(".myshopify.com", "");
54	}
55	
56	/**
57	 * Build the full From address with display name.
58	 *
59	 * - Custom sender name set:  "Cool Store via Pinzo <noreply@boldteq.app>"
60	 * - No custom name:          "cool-store via Pinzo <noreply@boldteq.app>"
61	 */
62	function buildFrom(shop: string, options?: EmailOptions): string {
63	  const displayName = options?.senderName?.trim() || shopFallbackName(shop, options);
64	  return `${displayName} via Pinzo <${getRawFromEmail()}>`;
65	}
66	
67	/**
68	 * Build optional reply_to field. Returns undefined when not configured
69	 * so it can be spread into the Resend payload without adding an empty header.
70	 */
71	function buildReplyTo(options?: EmailOptions): { reply_to: string } | Record<string, never> {
72	  const replyTo = options?.replyTo?.trim();
73	  if (replyTo) return { reply_to: replyTo };
74	  return {};
75	}
76	
77	/**
78	 * Wrap email body content in a branded layout with Pinzo logo header and store name.
79	 */
80	const APP_URL = process.env.SHOPIFY_APP_URL || "https://zip-code-checker-production-b1a0.up.railway.app";
81	
82	function emailLayout(storeName: string, body: string): string {
83	  return `
84	    <div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;background:#ffffff">
85	      <div style="padding:24px 24px 16px;border-bottom:1px solid #e5e7eb;text-align:center">
86	        <table cellpadding="0" cellspacing="0" border="0" style="margin:0 auto">
87	          <tr>
88	            <td style="vertical-align:middle;padding-right:10px">
89	              <img src="${APP_URL}/pinzo-logo.svg" alt="Pinzo" width="36" height="36" style="display:block;border-radius:8px" />
90	            </td>
91	            <td style="vertical-align:middle">
92	              <span style="font-size:20px;font-weight:700;color:#1a1a1a;letter-spacing:-0.3px">Pinzo</span>
93	            </td>
94	          </tr>
95	        </table>
96	        <p style="margin:8px 0 0;font-size:13px;color:#6b7280">${storeName}</p>
97	      </div>
98	      <div style="padding:24px">
99	        ${body}
100	      </div>
101	      <div style="padding:16px 24px;border-top:1px solid #e5e7eb;text-align:center">
102	        <p style="margin:0;font-size:12px;color:#9ca3af">Powered by <span style="color:#008060;font-weight:600">Pinzo</span></p>
103	      </div>
104	    </div>
105	  `;
106	}
107	
108	// ---------------------------------------------------------------------------
109	// 1. Waitlist Confirmation  (App → Customer)
110	// ---------------------------------------------------------------------------
111	
112	export async function sendWaitlistConfirmation(
113	  to: string,
114	  zipCode: string,
115	  shop: string,
116	  options?: EmailOptions,
117	): Promise<boolean> {
118	  const resend = getClient();
119	  if (!resend) return false;
120	
121	  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
122	
123	  try {
124	    await resend.emails.send({
125	      from: buildFrom(shop, options),
126	      to,
127	      subject: `You're on the waitlist — ${name}`,
128	      html: emailLayout(name, `
129	          <h2 style="margin:0 0 16px;color:#1a1a1a">You're on the waitlist!</h2>
130	          <p style="color:#374151;line-height:1.6">Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
131	          <p style="color:#6b7280;font-size:13px;margin-top:24px">— ${name}</p>
132	      `),
133	      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
134	      ...buildReplyTo(options),
135	    });
136	    return true;
137	  } catch (error) {
138	    console.error("[email] Failed to send waitlist confirmation:", error);
139	    return false;
140	  }
141	}
142	
