167	          <table style="margin:16px 0;border-collapse:collapse">
168	            <tr><td style="padding:4px 12px 4px 0;color:#6b7280">Email</td><td style="color:#1a1a1a">${customerEmail}</td></tr>
169	            <tr><td style="padding:4px 12px 4px 0;color:#6b7280">ZIP Code</td><td style="color:#1a1a1a">${zipCode}</td></tr>
170	          </table>
171	          <p style="color:#6b7280;font-size:13px">You can manage the waitlist from your <strong>${name}</strong> admin dashboard.</p>
172	      `),
173	      text: `New waitlist signup\n\nA customer (${customerEmail}) just joined the waitlist for ZIP code ${zipCode}.\n\nManage the waitlist from your ${name} admin dashboard.`,
174	      ...buildReplyTo(options),
175	    });
176	    return true;
177	  } catch (error) {
178	    console.error("[email] Failed to send merchant waitlist alert:", error);
179	    return false;
180	  }
181	}
182	
183	// ---------------------------------------------------------------------------
184	// 3. ZIP Available Notification  (App → Customer)
185	// ---------------------------------------------------------------------------
186	
187	export async function sendZipAvailableNotification(
188	  to: string,
189	  zipCode: string,
190	  shop: string,
191	  shopUrl: string,
192	  options?: EmailOptions,
193	): Promise<boolean> {
194	  const resend = getClient();
195	  if (!resend) {
196	    console.warn("[email] sendZipAvailableNotification skipped — Resend client not initialized (RESEND_API_KEY missing)");
197	    return false;
198	  }
199	
200	  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
201	
202	  try {
203	    await resend.emails.send({
