138	  var PRODUCT_ID = container.dataset.productId || null;
139	  // app.url resolves to the App Proxy URL (e.g. https://store.myshopify.com/apps/zipcheck).
140	  // If for any reason it is empty (e.g. dev environment or Shopify Liquid context issue),
141	  // fall back to the relative proxy path so the request still routes correctly through
142	  // Shopify's App Proxy rather than hitting the store's own domain as a missing route.
143	  var _rawApi = (container.dataset.api || "").replace(/\/$/, "");
144	  var _proxyPath = (container.dataset.proxy || "/apps/zipcheck").replace(/\/$/, "");
145	  // Prefer app.url when it looks like a full URL; otherwise use the relative proxy path
146	  // (which Shopify will forward to our app via the App Proxy config).
