23	function calculateDeliveryDate(
24	  estimatedDays: string,
25	  daysOfWeek: string | null,
26	): string | null {
27	  const match = estimatedDays.match(/^(\d+)/);
28	  if (!match) return null;
29	  const minDays = parseInt(match[1], 10);
30	  if (isNaN(minDays) || minDays < 0) return null;
31	
32	  const deliveryDayNames = daysOfWeek
33	    ? daysOfWeek.split(",").map((d) => d.trim().toLowerCase())
34	    : ["mon", "tue", "wed", "thu", "fri"];
35	
36	  const dayMap: Record<string, number> = {
37	    sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6,
38	  };
39	  const deliveryDayNumbers = new Set(
40	    deliveryDayNames.map((d) => dayMap[d]).filter((n) => n !== undefined),
41	  );
42	
43	  if (deliveryDayNumbers.size === 0) {
44	    [1, 2, 3, 4, 5].forEach((d) => deliveryDayNumbers.add(d));
45	  }
46	
47	  const date = new Date();
48	  let businessDaysAdded = 0;
49	
50	  while (businessDaysAdded < minDays) {
51	    date.setDate(date.getDate() + 1);
52	    if (deliveryDayNumbers.has(date.getDay())) {
53	      businessDaysAdded++;
54	    }
55	  }
56	
57	  while (!deliveryDayNumbers.has(date.getDay())) {
58	    date.setDate(date.getDate() + 1);
59	  }
60	
61	  return date.toISOString().split("T")[0];
62	}
63	
64	const CORS_HEADERS = {
65	  "Access-Control-Allow-Origin": "*",
66	  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
67	  "Access-Control-Allow-Headers": "Content-Type",
68	  "Content-Type": "application/json",
69	};
70	
71	// Applied only to successful (allowed) ZIP check responses to reduce DB load
72	// for repeated lookups of the same ZIP code from the same storefront visitor.
73	const SUCCESS_HEADERS = {
74	  ...CORS_HEADERS,
75	  "Cache-Control": "public, max-age=60, stale-while-revalidate=120",
76	};
77	
78	// Short cache for denied/not-found responses so merchants see changes quickly
79	// (e.g. when they add a new ZIP code it takes effect within 5 seconds).
80	const DENY_HEADERS = {
81	  ...CORS_HEADERS,
82	  "Cache-Control": "no-cache, max-age=5",
83	};
84	
85	const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
86	
87	/**
88	 * Returns true if a delivery rule's geographic constraints (zone or explicit
89	 * zip codes) match the given normalized zip and its zone.
90	 * Product/collection rules can optionally layer geographic constraints on top.
91	 * A rule with no zone and no zipCodes matches all geographies.
92	 */
93	function matchesZipOrZone(
94	  rule: { zipCodes: string | null; zone: string | null },
95	  normalizedZip: string,
96	  zipZone: string | null,
97	): boolean {
98	  if (rule.zipCodes?.trim()) {
99	    const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
100	    return zips.includes(normalizedZip);
101	  }
102	  if (rule.zone) {
103	    return rule.zone === zipZone;
104	  }
105	  // No geographic constraint — matches everywhere
106	  return true;
107	}
108	
109	async function handleZipCheck(
110	  shop: string | null,
111	  zip: string | null,
112	  productId?: string | null,
113	) {
114	  if (!shop || !zip) {
115	    return new Response(
116	      JSON.stringify({ error: "Missing shop or zip parameter" }),
117	      { status: 400, headers: CORS_HEADERS },
118	    );
119	  }
120	
121	  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
122	  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
123	    return new Response(
