34	// Handle CORS preflight
35	export const loader = async ({ request }: LoaderFunctionArgs) => {
36	  if (request.method === "OPTIONS") {
37	    return new Response(null, { status: 204, headers: CORS_HEADERS });
38	  }
39	  return new Response(JSON.stringify({ error: "Method not allowed" }), {
40	    status: 405,
41	    headers: CORS_HEADERS,
42	  });
43	};
44	
45	export const action = async ({ request }: ActionFunctionArgs) => {
46	  if (request.method === "OPTIONS") {
47	    return new Response(null, { status: 204, headers: CORS_HEADERS });
48	  }
49	
50	  if (request.method !== "POST") {
51	    return new Response(JSON.stringify({ error: "Method not allowed" }), {
52	      status: 405,
53	      headers: CORS_HEADERS,
54	    });
55	  }
56	
57	  // Rate limit: 10 signups per IP per minute (write operation — tighter limit)
58	  const ip = getClientIp(request);
59	  const { limited, resetAt } = rateLimit(`waitlist:${ip}`, 10, 60_000);
60	  if (limited) return rateLimitResponse(resetAt, CORS_HEADERS);
61	
62	  let shop: string | null = null;
63	  let zip: string | null = null;
64	  let email: string | null = null;
65	  let name: string | null = null;
66	
67	  try {
68	    const body = await request.json();
69	    shop = body?.shop ?? null;
70	    zip = body?.zip ?? null;
71	    email = body?.email ?? null;
72	    name = body?.name ?? null;
73	  } catch {
74	    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
75	      status: 400,
76	      headers: CORS_HEADERS,
77	    });
78	  }
79	
80	  if (!shop || !zip || !email) {
81	    return new Response(
82	      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
83	      { status: 400, headers: CORS_HEADERS },
84	    );
85	  }
86	
87	  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
88	  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
89	    return new Response(
90	      JSON.stringify({ error: "Invalid shop parameter" }),
91	      { status: 400, headers: CORS_HEADERS },
92	    );
93	  }
94	
95	  // Enforce input length limits to prevent abuse
96	  if (zip.length > 20 || email.length > 254) {
97	    return new Response(
98	      JSON.stringify({ error: "Invalid input" }),
99	      { status: 400, headers: CORS_HEADERS },
100	    );
101	  }
102	
103	  // Email validation — requires alphanumeric local, valid domain with TLD 2+ chars.
104	  // Intentionally stricter than the lax \S@\S.\S pattern to reject obvious
105	  // garbage like "a@b.c" or "x@localhost" while still allowing common formats.
106	  if (!/^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,24}$/.test(email)) {
107	    return new Response(
108	      JSON.stringify({ error: "Invalid email address" }),
109	      { status: 400, headers: CORS_HEADERS },
110	    );
111	  }
112	
113	  // Check if shop's plan allows waitlist
114	  try {
115	    const subscription = await getShopSubscription(shop);
116	    if (subscription.limits.maxWaitlist === 0) {
117	      return new Response(
118	        JSON.stringify({ error: "Waitlist is not available on this store's plan" }),
119	        { status: 400, headers: CORS_HEADERS },
120	      );
121	    }
122	    // Enforce entry limit for Starter plan
123	    if (subscription.limits.maxWaitlist < UNLIMITED) {
124	      const currentCount = await db.waitlistEntry.count({ where: { shop } });
125	      if (currentCount >= subscription.limits.maxWaitlist) {
126	        return new Response(
127	          JSON.stringify({ error: "Waitlist is currently full. Please try again later." }),
128	          { status: 400, headers: CORS_HEADERS },
129	        );
130	      }
131	    }
132	  } catch {
133	    // If subscription check fails, deny the request to prevent plan bypass
134	    return new Response(
135	      JSON.stringify({ error: "Unable to verify subscription. Please try again later." }),
136	      { status: 503, headers: CORS_HEADERS },
137	    );
138	  }
139	
140	  try {
141	    const normalizedZip = normalizeZipCode(zip);
142	
143	    await db.waitlistEntry.upsert({
144	      where: {
145	        shop_email_zipCode: {
146	          shop,
147	          email,
148	          zipCode: normalizedZip,
149	        },
150	      },
151	      create: {
152	        shop,
153	        email,
154	        name: name ? name.trim().substring(0, 100) : null,
155	        zipCode: normalizedZip,
156	        status: "waiting",
157	      },
158	      update: {
159	        status: "waiting",
160	      },
161	    });
162	
163	    // Fire-and-forget: fetch email settings then send emails.
164	    // We explicitly capture non-null shop/email for the closure so TS narrows
165	    // nullable types, and we log every failure so merchants can diagnose.
166	    const finalEmail = email;
167	    const finalShop = shop;
168	    db.shopSettings
169	      .findUnique({ where: { shop: finalShop } })
170	      .then((settings) => {
171	        const emailOpts: EmailOptions = {
172	          senderName: settings?.emailSenderName,
173	          shopDisplayName: settings?.shopName,
174	          replyTo: settings?.emailReplyTo,
175	        };
176	
177	        sendWaitlistConfirmation(finalEmail, normalizedZip, finalShop, emailOpts).catch(
178	          (err) =>
179	            console.error(
180	              "[api.waitlist] customer confirmation send failed shop=%s email=%s:",
181	              finalShop,
182	              finalEmail,
183	              err,
184	            ),
185	        );
186	
187	        if (settings?.notificationEmail) {
188	          sendMerchantWaitlistAlert(
189	            settings.notificationEmail,
190	            finalEmail,
191	            normalizedZip,
192	            finalShop,
193	            emailOpts,
194	          ).catch((err) =>
195	            console.error(
196	              "[api.waitlist] merchant alert send failed shop=%s:",
197	              finalShop,
198	              err,
199	            ),
200	          );
201	        }
202	      })
203	      .catch((err) =>
204	        console.error(
205	          "[api.waitlist] shop settings lookup failed for email dispatch shop=%s:",
206	          finalShop,
207	          err,
208	        ),
209	      );
210	
211	    return new Response(
212	      JSON.stringify({
213	        success: true,
214	        message: "You've been added to the waitlist!",
215	      }),
216	      { status: 200, headers: CORS_HEADERS },
217	    );
218	  } catch (err) {
219	    const mask = (s: string | null | undefined) => (s ? s.slice(0, 2) + "***" : "");
220	    console.error(
221	      "[api.waitlist] upsert failed shop=%s zip=%s email=%s:",
